window.TEXTP = window.TEXTP || {};
window.TEXTP["49.8"] = [[["p","522 ― ′Абдуллах ибн ′Аббас (да будет доволен Аллах им и его отцом) передал, что посланник Аллаха (да благословит его Аллах и приветствует) сказал: <b><i>«Пророков (ждут) минбары из золота, на которые они сядут. Но мой минбар останется (пустым), ибо я не сяду на него. Я буду стоять пред Аллахом, боясь, что меня отправят в Рай, а моя община останется (стоять) после меня. Я скажу: \"Господь мой! Моя община! Моя община!\". Всемогущий и Великий Аллах скажет: \"О Мухаммад! Как ты хочешь, чтобы Мы поступили с твоей общиной?\". Я отвечу: \"О Господь мой! Поскорее проведи расчёт между ними!\", после чего их позовут и проведут расчёт. Некоторые из них войдут в Рай по милости Аллаха, а некоторые войдут в Рай посредством моего заступничества. Я буду неустанно заступаться, пока мне не будут даны книги тех людей, которых уже увели в Ад, и пока Малик — хранитель Ада — не скажет: \"О Мухаммад! Ты не оставил для Огня, который является гневом твоего Господа, возможности наказать свою общину\"»</i></b><sup class=\"fn\">673</sup>."],["n",[[673,"Ат-Табарани в «аль-Аусат», 2937; аль-Хаким в «аль-Мустадрак», 220. Мукбиль аль-Уади′и назвал хадис отвергаемым (мункар). См. «аш-Шафа′а», 66."]]],["p","523 ― Катада передал со слов Анаса (да будет доволен им Аллах) хадис, в котором пришло, что люди скажут в Судный День, обращаясь к Адаму: <b><i>«Заступись за нас пред твоим Господом, чтобы Он избавил нас от этого нашего положения!». </i></b>Затем в этом хадисе говорится об обращении с просьбами и к другим пророкам<sup class=\"fn\">674</sup>."],["n",[[674,"Данный хадис придёт в полном в виде под № 526."]]],["p","ГЛАВА 53: РАЗЪЯСНЕНИЕ ТОГО, ЧТО ЭТО ЗАСТУПНИЧЕСТВО, ОПИСАННОЕ НАМИ, КАК ПЕРВОЕ ЗАСТУПНИЧЕСТВО, ПРОИЗОЙДЁТ ДО ТОГО, КАК ЛЮДИ БУДУТ ПРОХОДИТЬ ПО МОСТУ (СЫРАТ), А ИМЕННО ТОГДА, КОГДА БУДЕТ ПРИБЛИЖЕН РАЙ."],["p","Аллах сказал: <b>«Рай будет приближен к богобоязненным»</b><sup class=\"fn\">675</sup>."],["n",[[675,"Сура «аш-Шу′ара», аят 90."]]],["p","524 ― Абу Хурейра (да будет доволен им Аллах) и Хузейфа (да будет доволен им Аллах) передали, что посланник Аллаха (да благословит его Аллах и приветствует) сказал: <b><i>«Аллах соберёт людей, и верующие останутся стоять до тех пор, пока к ним не будет приближен Рай. Тогда они придут к Адаму и скажут: \"О отец наш! Попроси, чтобы Рай открыли для нас\". Он ответит: \"А разве не грех вашего отца, Адама, стал единственной причиной вашего изгнания из Рая?! Это не в моих силах\"». </i></b>"],["p","[Затем упоминается часть хадиса, после чего сказано]:"],["p","<b><i>«Люди придут к Мусе, но он скажет: \"Это не в моих силах. Идите к ′Исе, слову Аллаха и духу Его\". Но ′Иса скажет: \"Это не в моих силах\". Затем они придут к Мухаммаду, который встанет (у трона), и ему будет позволено (заступаться за людей). Потом будут посланы залог (амана) и родственные связи, которые встанут справа и слева по обеим сторонам Моста (сырат), а потом первый из вас пройдёт (по нему), подобно молнии». </i></b>"]],[["p","Я<sup class=\"fn\">676</sup> сказал: <i>«Да станут отец мой и мать выкупом за тебя! Что значит \"подобно молнии\"?». </i>Пророк (да благословит его Аллах и приветствует) сказал: <b><i>«Разве не видели вы, как молния появляется и исчезает в мгновении ока?! Следующие пронесутся подобно ветру, а следующие — подобно птицам или быстро бегущим людям. Их будут подгонять их дела</i></b><sup class=\"fn\">677</sup><b><i>, а ваш пророк будет стоять на Мосту (сырат), повторяя: \"Господь мой! Спаси! Спаси!\". (Это будет продолжаться) до тех пор, пока (очередь не дойдёт до тех) людей, чьи дела окажутся слабыми, и пока не придёт человек, который сможет передвигаться только ползком. А по обеим сторонам Моста подвесят крюки, которые получат веление хватать тех, кого им велят, и кто-то будет оцарапан, но спасётся, а кого-то столкнут в Огонь связанным». </i></b>"],["n",[[676,"Этот вопрос задал либо Абу Хурейра, либо Хузейфа, со слов которых был передан этот хадис. Да будет доволен ими Аллах."],[677,"Иначе говоря, чем больше благих дел окажется в запасе у человека, тем быстрее он преодолеет этот мост."]]],["p","Абу Хурейра сказал: <i>«Клянусь Тем, в Чьей руке душа Абу Хурейры! Чтобы достичь дна Геенны, потребуется семьдесят лет!»</i><sup class=\"fn\">678</sup>."],["n",[[678,"Муслим, 195; Абу Я′ля, 6216; аль-Хаким в «аль-Мустадрак», 8749."]]],["p","ГЛАВА 54: РАЗЪЯСНЕНИЕ ТОГО, ЧТО В ДЕНЬ ВОСКРЕСЕНИЯ ПРОРОКУ (ДА БЛАГОСЛОВИТ ЕГО АЛЛАХ И ПРИВЕТСТВУЕТ) БУДУТ ДАРОВАНЫ РАЗНЫЕ ВИДЫ ЗАСТУПНИЧЕСТВА, КОТОРЫЕ БУДУТ ПРОИСХОДИТЬ ДРУГ ЗА ДРУГОМ В ОДНОМ МЕСТЕ"],["p","Первое заступничество упомянуто в хадисе, который передал Абу Зур′а со слов Абу Хурейры (да будет доволен им Аллах), а также в хадисе со слов Ибн ′Умара и Ибн ′Аббаса (да будет доволен ими Аллах). Здесь пророк (да благословит его Аллах и приветствует) будет заступаться за свою общину, чтобы избавить их от долгого стояния, и чтобы Аллах поскорее начал расчёт и рассудил их. Затем будет еще заступничество о том, чтобы вывести приверженцев единобожия из Огня. Их будут выводить группу за группой посредством его заступничества. Мы упомянем на эту тему хадис в сокращённом виде. Мы опустим первую часть этого хадиса."],["p","525 ― Пророк (да благословит его Аллах и приветствует) сказал: <b><i>«Мне было даровано умение кратко говорить»</i></b><sup class=\"fn\">679</sup>."],["n",[[679,"Данная версия хадиса является слабой, но есть похожий достоверный хадис. Пришло со слов Абу Хурейры (да будет доволен им Аллах), что пророк (да благословит его Аллах и приветствует) сказал: <b><i>«Я был послан с краткими, но вмещающими в себя много смысла словами». </i></b>Аль-Бухари, 2977; Муслим, 523."]]],["p","Бывало так, что сподвижники пророка (да благословит его Аллах и приветствует) передавали его слова с сокращениями, когда передавали их. А иногда они передавали хадис целиком. Бывало так, что некоторые слушатели хадиса запоминали лишь часть хадиса, а не весь хадис целиком. Бывало и так, что какие-то передатчики забывали часть хадиса. И вот когда мы собираем все версии хадисов, мы уже понимаем, каким был полный текст. Поэтому и в нашей книге мы можем упоминать некоторые хадисы пророка (да благословит его Аллах и приветствует) с сокращениями, а некоторые — полностью. Если человек не понимает этот вопрос, то ему не разрешено заниматься хадисоведением и не разрешено притязать на знание этой науки."]],[["p","526 ― Анас ибн Малик (да будет доволен им Аллах) передал, что посланник Аллаха (да благословит его Аллах и приветствует) сказал: <b><i>«В День Воскресения (люди) будут собраны и станут переживать по этому поводу. Тогда они скажут: \"Не отправиться ли нам к тому, кто заступится за нас пред нашим Господом и избавит нас от нахождения здесь?!\". Тогда они придут к Адаму и скажут: \"Ты — Адам! Аллах создал тебя Своей рукой, вдохнул в тебя дух от Него и поселил тебя в Своём Раю. Заступись же за нас пред твоим Господом!\". Он ответит: \"Я — не для этого!\" — и упомянет свой грех — \"Ступайте к Нуху. Он — первый пророк, которого Аллах послал к мирам\". </i></b>"],["p","<b><i>Тогда они придут к Нуху и скажут: \"Ступай и заступись за нас пред твоим Господом!\". Он ответит: \"Я — не для этого!\" — и упомянет свой грех — \"Ступайте к Ибрахиму. Он — раб, которого Аллах сделал Своим любимым!\".</i></b>"],["p","<b><i>Они придут к Ибрахиму и скажут: \"Ступай и заступись за нас пред твоим Господом!\". Он ответит: \"Я — не для этого!\" — и упомянет, как три раза солгал — \"Ступайте к Мусе. Он — раб, с которым Аллах говорил словами\". </i></b>"],["p","<b><i>Они придут к Мусе и скажут: \"Ступай и заступись за нас пред твоим Господом!\". Он ответит: \"Я — не для этого!\" — и упомянет свой грех — \"Ступайте к ′Исе. Он — дух от Аллаха, Его слово, Его раб и Его посланник\". </i></b>"],["p","<b><i>Они придут к ′Исе и скажут: \"Ступай и заступись за нас пред твоим Господом!\". Он ответит: \"Я — не для этого!\" — но не упомянет какой-либо грех — \"Идите к Мухаммаду. Он — раб, которому Аллах простил все прошлые и будущие грехи\".</i></b>"],["p","<b><i>Тогда они придут ко мне, и я встану, возьмусь за кольцо (на вратах) Рая и попрошу разрешения, и мне будет разрешено. А когда я увижу Его, я паду ниц\". (Аллах) скажет: \"Подними свою голову! Говори, и тебя услышат, заступайся, и твоё заступничество будет принято, проси, и тебе будет даровано!\". Тогда для меня выведут группу из Огня, после чего я скажу: \"О Господь мой! Не осталось в Огне никого, кроме тех, кого удержал (там) Коран\"»</i></b><sup class=\"fn\">680</sup>."],["n",[[680,"Цепочка передатчиков, по которой привёл этот хадис Ибн Хузейма (да помилует его Аллах), является слабой, но сам хадис является достоверным. Его достоверная версия будет приведена под № 528."]]],["p","527 ― Также он передал, что посланник Аллаха (да благословит его Аллах и приветствует) сказал: <b><i>«Поистине, у каждого пророка была мольба, с которой он обращался за свою общину. Я же припас свою мольбу для заступничества за свою общину в День Воскресения»</i></b><sup class=\"fn\">681</sup>."],["n",[[681,"Аль-Бухари, 6305; Муслим, 200, и др."]]],["p","528-529 ― Анас (да будет доволен им Аллах) передал, что пророк (да благословит его Аллах и приветствует) сказал: <b><i>«Верующие придут к Адаму в День Воскресения и скажут: \"Аллах повелел ангелам поклониться тебе. Заступись же за нас пред Аллахом, чтобы Он избавил нас от стояния здесь!\", но он ответит: \"Я — не для этого. Идите к Нуху\". Они придут к Нуху, но он скажет: \"Я — не для этого\", после чего им будет приказано пойти к любимцу Аллаха Ибрахиму. Они придут к Ибрахиму, но он ответит: \"Я — не для этого. Идите к ′Исе. Поистине, он — дух от Аллаха и Его слово\". Тогда они придут к ′Исе, но он ответит: \"Я — не для этого. Идите к Мухаммаду, ведь Аллах простил ему все прошлые и будущие грехи\". </i></b>"]],[["p","<b><i>Тогда они придут ко мне, а я пойду к своему Всемогущему и Великому Господу, в Его обитель. Я попрошу разрешения, и мне будет позволено, и когда я увижу своего Господа, я паду пред Ним ниц, и Он оставит меня в таком положении столько, сколько пожелает. Потом будет сказано (или: Он скажет): \"Поднимайся, Мухаммад! Говори, и тебя услышат, проси, и тебе будет даровано, заступайся, и твоё заступничество будет принято!\". Я начну восхвалять своего Господа такими похвалами, которым Он меня обучит, а затем я стану заступаться, и для меня выведут группу, и я введу их в Рай. Затем я во второй раз вернусь к своему Господу, и когда я увижу своего Господа, я паду ниц, и Он оставит меня в таком положении столько, сколько пожелает. Потом будет сказано (или: Он скажет): \"Поднимайся, Мухаммад! Проси, и тебе будет даровано, заступайся, и твоё заступничество будет принято!\". Я начну восхвалять своего Господа такими похвалами, которым Он меня обучит, а затем я стану заступаться, и для меня выделят группу, и я выведу их (из Ада) и введу в Рай. Затем я в третий раз вернусь к своему Господу, и когда я увижу своего Господа, я паду ниц, и Он оставит меня в таком положении столько, сколько пожелает. Потом будет сказано (или: Он скажет): \"Поднимайся, Мухаммад! Говори, и тебя услышат, проси, и тебе будет даровано, заступайся, и твоё заступничество будет принято!\". Я начну восхвалять своего Господа такими похвалами, которым Он меня обучит, а затем я стану заступаться, и для меня выделят группу, и я выведу их (из Ада) и введу в Рай. И так до тех пор, пока я не скажу своему Господу: \"Не осталось в Огне никого, кроме тех, кого удержал (там) Коран\"</i></b><sup class=\"fn\">682</sup><b><i>»</i></b><sup class=\"fn\">683</sup>."],["n",[[682,"То есть, кроме тех, о ком Коран сообщил, что они останутся в Аду навечно."],[683,"Аль-Бухари, 4476, 7410, 7516; Муслим, 193, и др."]]],["p","530 ― В другой версии со слов Анаса ибн Малика (да будет доволен им Аллах) пришло, что посланник Аллаха (да благословит его Аллах и приветствует) сказал: <b><i>«Верующие соберутся в День Воскресения и станут переживать по этому поводу (или: им будет внушено искать заступника). Тогда они скажут: \"О, если бы мы нашли заступника пред нашим Всемогущим и Великим Господом, чтобы Он избавил нас от нахождения в этом месте!\". И вот они придут к Адаму и скажут: \"О Адам! Ты — отец людей! Аллах сотворил тебя Своей рукой, велел Своим ангелам поклониться тебе и научил тебя именам всех вещей. Заступись же за нас пред своим Господом, чтобы Он избавил нас от нахождения в этом месте!\". Он скажет: \"Я — не для этого!\", и упомянет им свой грех, который он совершил и из-за которого ему стыдно пред его Господом. (Затем он скажет): \"Но идите к Нуху. Поистине, он — первый посланник, которого Аллах отправил к жителям земли\". </i></b>"]],[["p","<b><i>Когда они придут к Нуху, он скажет: \"Я — не для этого!\", и упомянет им, что однажды попросил своего Господа о том, о чём у него не было знаний, и из-за этого ему стыдно пред своим Господом. (Затем он скажет): \"Но идите к Ибрахиму, любимцу Милостивого\". </i></b>"],["p","<b><i>Когда они придут к нему, он скажет: \"Я — не для этого! Идите к Мусе. Он — раб, с которым Аллах говорил и которому Он даровал Тору\". </i></b>"],["p","<b><i>Они придут к нему, но он скажет: \"Я — не для этого!\", и упомянет, что однажды он убил человека не в качестве мести за смерть другого человека, и из-за этого ему стыдно пред своим Господом. (Затем он скажет): \"Но идите к ′Исе. Он — раб Аллаха, Его посланник, слово Аллаха и дух от Него\". </i></b>"],["p","<b><i>Они придут к нему, но он скажет: \"Я — не для этого! Ступайте к Мухаммаду, к рабу, которому Аллах простил все прошлые и будущие грехи\". Тогда они придут ко мне, и я пойду…». </i></b>"],["p","В версии аль-Хасана (аль-Басри) сказано: <b><i>«И я пройду между двумя рядами верующих». </i></b>"],["p","Затем в версии Анаса сказано: <b><i>«Я попрошу разрешения обратиться к своему Господу, и мне будет разрешено, и когда я увижу Его, я паду пред Ним ниц, и Он оставит меня в таком положении столько, сколько пожелает. Затем будет сказано: \"О Мухаммад! Поднимайся! Говори, и тебя услышат, проси, и тебе будет даровано, заступайся, и твоё заступничество будет принято!\". Я подниму голову и воздам (Аллаху) такую хвалу, которой Он меня научит. Я начну заступаться, и для меня выделят группу, и я введу их в Рай. </i></b>"],["p","<b><i>Затем я вернусь во второй раз, и когда я увижу своего Господа, я паду пред Ним ниц, и Он оставит меня в таком положении столько, сколько пожелает. Затем будет сказано: \"О Мухаммад! Поднимайся! Говори, и тебя услышат, проси, и тебе будет даровано, заступайся, и твоё заступничество будет принято!\". Я подниму голову и воздам Аллаху такую хвалу, которой Он меня научит. Я начну заступаться, и для меня выделят группу, и я введу их в Рай.</i></b>"],["p","<b><i>Затем я вернусь в третий раз, и когда я увижу своего Господа, я паду пред Ним ниц, и Он оставит меня в таком положении столько, сколько пожелает. Затем будет сказано: \"О Мухаммад! Поднимайся! Говори, и тебя услышат, проси, и тебе будет даровано, заступайся, и твоё заступничество будет принято!\". Я подниму голову и воздам Аллаху такую хвалу, которой Он меня научит. Я начну заступаться, и для меня выделят группу, и я введу их в Рай.</i></b>"],["p","<b><i>Затем я вернусь в четвёртый раз и скажу: \"О Господь мой! Не осталось никого, кроме того, кого задержал (в Аду) Коран\"»</i></b><sup class=\"fn\">684</sup>."],["n",[[684,"Муслим, 193; ан-Насаи в «ас-Сунан аль-кубра», 11243; Ибн Маджа, 4312; Ахмад, 3/116; Ибн Аби ′Асым в «ас-Сунна», 807, 808, 810; Ибн Аби Шейба в «Мусаннафе», 31677."]]]],[["p","В этом хадисе сказано: <b><i>«...и для меня выведут группу из Огня…». </i></b>Это указывает на то, что это заступничество уже не является тем первым заступничеством, о котором говорится в хадисе со слов Абу Хурейры (да будет доволен им Аллах). Первое заступничество было для того, чтобы Аллах избавил их от этого стояния, о котором говорится в хадисе со слов Ибн ′Умара (да будет доволен Аллах им и его отцом). Пророк (да благословит его Аллах и приветствует) попросит своего Всемогущего и Великого Господа рассудить творения. В хадисе со слов Ибн ′Аббаса (да будет доволен Аллах им и его отцом) говорится, что он сначала попросит Аллаха ускорить их расчёт. Речь идёт о суде между ними. И тогда будут упомянуты люди, которые войдут в Рай по милости Аллаха, и это — те люди, которые войдут в Рай без расчёта. О них говорится в хадисе со слов Абу Хурейры (да будет доволен им Аллах). И они — те, которые войдут в Рай через правые врата. И знай, что в хадисе со слов Ибн ′Аббаса (да будет доволен Аллах им и его отцом) говорится, что пророк (да благословит его Аллах и приветствует) будет много раз заступаться<sup class=\"fn\">685</sup>. Потому что в хадисе сказано: «Ля язалю» (<span class=\"ar-i\" lang=\"ar\" dir=\"rtl\">لا يزال</span>). Эту фразу используют арабы тогда, когда что-то происходит раз за разом. А в хадисе со слов Анаса сказано: (<span class=\"ar-i\" lang=\"ar\" dir=\"rtl\">ما زلت أشفع</span>) <b><i>«Я не буду переставать заступаться»</i></b>. Я приведу эту версию в другой главе."],["n",[[685,"То есть сначала пророк (да благословит его Аллах и приветствует) попросит Аллаха ускорить расчёт и облегчить верующим, а затем он уже много раз начнёт заступаться за обитателей Огня из числа мусульман."]]],["p","В версии, которую привёл Са′ид ибн Аби ′Аруба, сразу сказано: <b><i>«И мне будет выделена группа, и я введу их в Рай». </i></b>Возможно, имеются в виду те, о ком говорится в хадисе со слов Абу Хурейры (да будет доволен им Аллах). То есть те, которые войдут в Рай через правые врата без какого-либо расчёта. А, возможно, имеются в виду те мусульмане, которые выйдут из Огня."],["p","531 ― В другой версии со слов Анаса ибн Малика (да будет доволен им Аллах) пришло, что посланник Аллаха (да благословит его Аллах и приветствует) сказал: <b><i>«Поистине, люди будут воскрешены в День Воскресения и задержаны столько, сколько пожелает Аллах. Среди них будут и верующие, которые соберутся и скажут: \"Посмотрите, кто сможет заступиться за нас пред нашим Господом, чтобы Он отпустил нас с этого места\". Они отправятся ко всем пророкам, но все они ответят: \"Я — не для этого! Я — не для этого!\". Затем они вернутся к Адаму, который скажет им: \"О мои потомки! Как вы считаете, если бы кто-нибудь из вас положил свои вещи в мешочек, а затем запечатал его, мог бы он достать эти вещи, кроме как через эту печать?! Поистине, Мухаммад — печать пророков, и он откроет (Судный) Час. Вам следует отправиться к нему\". </i></b>"]],[["p","<b><i>Тогда они придут ко мне, после чего я подойду к вратам Рая и попрошу открыть их, и мне откроют. Когда же я увижу своего Господа, я паду пред Ним ниц, и Он оставит меня в земном поклоне столько, сколько пожелает. Затем Он обучит меня восхвалениям, которыми я стану восхвалять Его, и никто никогда прежде не восхвалял Его ими до меня, и никто не сделает этого после меня. Затем будет сказано: \"О Мухаммад! Заступайся, и твоё заступничество будет принято, проси, и тебе будет даровано!\". Затем я скажу: \"О Господь мой! Я заступаюсь за каждого маленького ребёнка\"», </i></b>имея в виду того, кто умер маленьким."],["p","<b><i>«И мне будет сказано: \"Это — не для тебя, о Мухаммад! Клянусь Моим величием, славой и могуществом! Я не оставлю в Огне раба, который умер, ничего не придавая Мне в сотоварищи, а непременно выведу его из Огня. И некий человек скажет: \"О Господь мой! У меня был товарищ. Запрети же Огню пожирать меня, чтобы я вывел своего товарища (из него)\", и Огню будет запрещено пожирать его, пока он не выведет своего товарища»</i></b><sup class=\"fn\">686</sup>."],["n",[[686,"Данная версия является слабой. На это указал сам Ибн Хузейма (да помилует его Аллах), который после его упоминания сказал: <i>«Если этот хадис достоверен…».</i> А Аллах знает лучше!"]]],["p","532 ― В другой версии со слов Анаса (да будет доволен им Аллах) пришло, что посланник Аллаха (да благословит его Аллах и приветствует) сказал: <b><i>«Когда верующие соберутся в День Воскресения…», </i></b>а затем упомянул длинный хадис, после чего сказал: <b><i>«Я приду к Аллаху в четвёртый раз и скажу: \"О Господь мой! Не осталось в Огне никого, кроме того, кого задержал Коран\"». </i></b>Катада (передатчик этого хадиса) сказал: <i>«Речь идёт о тех, кто останется в Аду навечно». </i>"],["p","Также Катада сказал: «Анас ибн Малик (да будет доволен им Аллах) рассказал мне, пророк Аллаха (да благословит его Аллах и приветствует) сказал: <b><i>«Из Огня выйдет тот, кто сказал: \"Нет истинного бога, кроме Аллаха\" (ля иляха илля Ллах), если при этом в его сердце было благо хотя бы весом с ячменное зёрнышко. А затем выйдет из Огня тот, кто сказал: \"Нет истинного бога, кроме Аллаха\" (ля иляха илля Ллах), и в его сердце было благо хотя бы размером с букашку»</i></b><sup class=\"fn\">687</sup>."],["n",[[687,"Данная версия является достоверной."]]],["p","533 ― Катада сказал: <i>«Обладатели знания считают, что достохвальное место (аль-мака́м аль-махму́д), о котором сказал Всемогущий и Великий Аллах: </i><b>\"Быть может, Господь твой возведет тебя на Достохвальное место\"</b><sup class=\"fn\">688</sup>, <i>это — заступничество (шафа′ат) в День Воскресения»</i><sup class=\"fn\">689</sup>."],["n",[[688,"Сура «аль-Исра», аят 79."],[689,"Также передал Ибн Джарир в «Тафсире», 8/129."]]],["p","Эти хадисы указывают на то, что пророк (да благословит его Аллах и приветствует) будет заступаться много раз. На эту тему есть ещё много хадисов, которые будут приведены далее, если Аллах окажет содействие и пожелает!"]],[["p","534 ― [Под этим номером приведено то же самое сообщение, что и под № 532]."],["p","535 ― [Под этим номером приведена ещё одна похожая версия со слов Анаса]."],["p","536 ― В другой версии со слов Анаса (да будет доволен им Аллах) пришло, что посланник Аллаха (да благословит его Аллах и приветствует) сказал: <b><i>«День Воскресения покажется для людей долгим, и они скажут друг другу: \"Пойдёмте к Адаму, отцу человечества, чтобы он заступился за нас пред своим Всемогущим и Великим Господом, чтобы Господь рассудил между нами\". Они придут к Адаму и скажут: \"О Адам! Ты — тот, которого Аллах сотворил Своей рукой. Он поселил тебя в Своём Раю и заставил ангелов поклониться тебе. Заступись же за нас пред своим Господом, чтобы Он рассудил между нами\". (Адам) ответит: \"Я — не для этого! Идите к Нуху, который был главой пророков\". </i></b>"],["p","<b><i>Они придут к Нуху и скажут: \"О Нух! Заступись за нас пред своим Господом, чтобы Он рассудил между нами\", но он ответит: \"Я — не для этого! Идите к Ибрахиму, любимцу Аллаха\". Они придут к Ибрахиму и скажут: \"О Ибрахим! Заступись за нас пред своим Господом, чтобы Он рассудил между нами\", но он ответит: \"Я — не для этого! Идите к Мусе, которого Аллах избрал Своим посланием и Своей речью\". Они придут к Мусе и скажут: \"О Муса! Заступись за нас пред своим Господом, чтобы Он рассудил между нами\", но он ответит: \"Я — не для этого! Идите к ′Исе, который был духом и словом Аллаха\". Они придут к ′Исе и скажут: \"О ′Иса! Заступись за нас пред своим Господом, чтобы Он рассудил между нами\", но он ответит: \"Я — не для этого! Как вы считаете, если бы вещи лежали в мешочке, на который была наложена печать, можно ли было бы добраться до содержимого мешочка без вскрытия печати?!\". Они ответят: \"Нет!\". Тогда он скажет: \"Мухаммад — это печать пророков. Он присутствует сегодня, и Аллах простил ему все прошлые и будущие грехи\"».</i></b>"],["p","Затем посланник Аллаха (да благословит его Аллах и приветствует) сказал: <b><i>«Они придут ко мне и скажут: \"О Мухаммад! Заступись за нас пред своим Господом, чтобы Он рассудил между нами\", а я отвечу им: \"Я — для этого!\". А когда Аллах разрешит (заступаться) тем, кому Он пожелает, и тем, кем Он доволен, я приду к вратам Рая и постучусь. Меня спросят: \"Кто ты?\", а я отвечу: \"Мухаммад\". Тогда мне откроют, и я приду к своему Господу, а Он будет на своём троне. Я паду ниц и стану восхвалять Его такими хвалами, которыми Его не восхвалял никто прежде, и которыми Его не будет восхвалять никто после меня. Он скажет: \"О Мухаммад! Подними свою голову! Говори, и тебя услышат, проси, и тебе будет даровано, заступайся, и твоё заступничество будет принято\". Я подниму голову и скажу: \"О Господь мой! Моя община! Моя община!\". Он скажет: \"Выведи тех, в чьём сердце было хотя бы на вес ячменного зёрнышка\". </i></b>"]],[["p","<b><i>Я выведу их, а затем вернусь и паду ниц, и стану восхвалять Его такими хвалами, которыми Его не восхвалял никто прежде, и которыми Его не будет восхвалять никто после меня. Он скажет: \"О Мухаммад! Подними свою голову! Говори, и тебя услышат, проси, и тебе будет даровано, заступайся, и твоё заступничество будет принято\". Я подниму голову и скажу: \"О Господь мой! Моя община! Моя община!\". Тогда Он скажет: \"Выведи тех, в чьём сердце было хотя бы на вес пшеничного зёрнышка\".</i></b>"],["p","<b><i>Я выведу их, а затем вернусь и стану восхвалять Его такими хвалами, которыми Его не восхвалял никто прежде, и которыми Его не будет восхвалять никто после меня. Он скажет: \"О Мухаммад! Подними свою голову! Говори, и тебя услышат, проси, и тебе будет даровано, заступайся, и твоё заступничество будет принято\". Я подниму голову и скажу: \"О Господь мой! Моя община! Моя община!\". Тогда Он скажет: \"Выведи тех, в чьём сердце было хотя бы на вес букашки\", и я выведу их»</i></b><sup class=\"fn\">690</sup>."],["n",[[690,"Также передали Ахмад, 13590, и Мухаммад ибн Наср аль-Марвази в «Та′зым кадр ас-салят», 265. Аль-Арнаут назвал этот хадис достоверным в соответствии с условиями Муслима. А Аллах знает лучше!"]]],["p","537 ― В версии, которую привёл Хумейд, сказано, что в третий раз Аллах скажет: <b><i>«Выведи тех, в чьём сердце было хотя бы что-то»</i></b><sup class=\"fn\">691</sup>."],["n",[[691,"Аль-Бухари, 7509; Ибн Манда в «аль-Иман», 874; Ибн Аби ′Асым в «ас-Сунна», 816."]]],["p","538 ― В другой версии со слов Анаса (да будет доволен им Аллах) пришло, что пророк Аллаха (да благословит его Аллах и приветствует) сказал: <b><i>«Поистине, (в День Воскресения) я буду стоять в ожидании прихода моей общины по мосту (Сырат), и придёт ко мне ′Иса ибн Марьям, и скажет: \"Эти пророки пришли к тебе, о Мухаммад! Они просят (разрешения) собраться возле тебя, чтобы ты попросил Аллаха, чтобы Он разделил людей, (направив их) туда, куда пожелает, ибо они находятся в тяжелом положении\". Творения же будут стоять в (собственном) поту, (который достигнет) их ртов. Что касается верующего, то этот пот будет для него, словно (легкая) простуда, а что касается неверующего, то его покроет смерть».</i></b>"],["p","Тогда пророк (да благословит его Аллах и приветствует) скажет: <b><i>«Жди, пока я не вернусь к тебе!».</i></b> И пророк Аллаха (да благословит его Аллах и приветствует) направится в сторону Трона и встанет пред ним, и увидит то, чего не видел ни избранный ангел, ни (другой) посланный пророк. Тогда Аллах внушит Джибрилю (следующие слова): «Направляйся к Мухаммаду и скажи ему: «Подними свою голову! Проси и тебе будет даровано, заступайся и твое заступничество будет принято!»."]],[["p","(Пророк, да благословит его Аллах и приветствует, рассказывал): <b><i>«Мое заступничество о моей общине будет принято, (и мне позволят) вывести одного человека из каждых девяносто девяти. А я буду возвращаться к своему Господу, и всякий раз мое заступничество будет приниматься (вновь и вновь), пока Аллах вовсе не скажет мне: \"О Мухаммад! Введи (в Рай) те творения Аллаха из твоей общины, которые засвидетельствовали, что нет истинного бога, кроме Аллаха, и скончались на этом\"»</i></b><sup class=\"fn\">692</sup>."],["n",[[692,"Ахмад, 3/178; ад-Дыя аль-Макдиси в «аль-Мухтара», 2695, 2696."]]],["p","ГЛАВА 55: РАЗЪЯСНЕНИЕ ТОГО, ЧТО ПРОРОК (ДА БЛАГОСЛОВИТ ЕГО АЛЛАХ И ПРИВЕТСТВУЕТ) — ЭТО ПЕРВЫЙ, КТО БУДЕТ ЗАСТУПАТЬСЯ, И ПЕРВЫЙ, ЗАСТУПНИЧЕСТВО КОТОРОГО БУДЕТ ПРИНЯТО В ДЕНЬ ВОСКРЕСЕНИЯ."],["p","В этом указание на то, что в День Воскресения после нашего пророка (да благословит его Аллах и приветствует) будут заступаться ещё другие, что я разъясню далее, если пожелает Аллах. Ведь в арабском языке нельзя назвать кого-то первым, если после него не будет второго и третьего."],["p","539 ― Анас (да будет доволен им Аллах) передал, что посланник Аллаха (да благословит его Аллах и приветствует) сказал: <b><i>«Я первым из людей стану ходатайствовать о Рае, и никому из пророков не поверит столько людей, сколько поверит мне, и был из числа пророков такой, которому поверил только один человек из его общины»</i></b><sup class=\"fn\">693</sup>."],["n",[[693,"Муслим, 196; Ибн Манда в «аль-Иман», 885-891; Ибн Аби Шейба в «Мусаннафе», 31651; аль-Бейхакы в «ас-Сунан аль-кубра», 9/4."]]],["p","540 ― Анас (да будет доволен им Аллах) также передал, что посланник Аллаха (да благословит его Аллах и приветствует) сказал: <b><i>«Мухаммад — посланник Аллаха, (и) в День Воскресения он будет первым, кто войдёт в Рай, и первым, кто станет заступаться».</i></b>"],["p","541 ― Абу Хурейра (да будет доволен им Аллах) передал, что посланник Аллаха (да благословит его Аллах и приветствует) сказал: <b><i>«Я — господин сынов Адама, и первый, над кем разверзнется земля, и первый, кто станет заступаться, и первый, заступничество которого будет принято»</i></b><sup class=\"fn\">694</sup><b><i>. </i></b>"],["n",[[694,"Ахмад, 2/540; Ибн Аби Шейба в «Мусаннафе», 31728, 35849. Также похожий хадис передали Муслим, 2278; Абу Дауд, 4673; аль-Лялякаи в «И′тикад ахли ссунна», 1452, 1453; аль-Бейхакы в «Шу′аб аль-иман», 1486, и др."]]],["p","542 ― В версии со слов Абу Са′ида аль-Худри (да будет доволен им Аллах) сказано: <b><i>«(Люди) придут к Мухаммаду, и я пойду и схвачусь за кольцо на райских вратах, и постучусь. (Ангелы) спросят: \"Кто это?\". Я отвечу: \"Мухаммад\". Тогда они скажут: \"Мухаммада уже отправили\", и поприветствуют меня»</i></b><sup class=\"fn\">695</sup>."],["n",[[695,"Ат-Тирмизи, 3148; ад-Дарими в «Сунан», 50. Здесь приведена малая часть длинного хадиса."]]]],[["p","ГЛАВА 56: УПОМИНАНИЕ СИЛЬНОГО СОСТРАДАНИЯ ПРОРОКА (ДА БЛАГОСЛОВИТ ЕГО АЛЛАХ И ПРИВЕТСТВУЕТ), ЕГО ДОБРОТЫ И МИЛОСТИ К ЧЛЕНАМ СВОЕЙ ОБЩИНЫ. УКАЗАНИЕ НА ПРЕВОСХОДСТВО ЕГО СОСТРАДАНИЯ К ЧЛЕНАМ СВОЕЙ ОБЩИНЫ НАД СОСТРАДАНИЕМ ДРУГИХ ПРОРОКОВ (МИР ИМ И БЛАГОСЛОВЕНИЕ АЛЛАХА) К ЧЛЕНАМ ИХ ОБЩИН"],["p","Всемогущий и Великий Аллах даровал каждому пророку мольбу, на которую обещал ответить. И каждый пророк из них обратился со своей мольбой уже в этом мире, и каждому из них был дарован ответ. Но наш пророк (да благословит его Аллах и приветствует) отложил свою мольбу, чтобы посвятить её заступничеству за членов своей общины, ибо ему были присущи особое сострадание, милосердие и доброта к членам своей общины. И Аллах воздал нашему пророку Мухаммаду (да благословит его Аллах и приветствует) наилучшим воздаянием среди всех посланников, и Аллах воскресит его в достохвальном месте, которое Аллах обещал ему, чтобы он заступился за членов своей общины. Поистине, наш Всемогущий и Великий Господь не нарушает Своих обещаний и Он ответит на мольбу Своего пророка (да благословит его Аллах и приветствует), которую тот отложил для заступничества за членов своей общины в День Воскресения."],["p","543 ― ′Абд ур-Рахман ибн Хурмуз передал со слов Абу Хурейры (да будет доволен им Аллах), что посланник Аллаха (да благословит его Аллах и приветствует) сказал: <b><i>«У каждого пророка была мольба, с которой он обращался, и ему давался ответ. А я, если пожелает Аллах, хочу отложить свою мольбу, чтобы заступиться за свою общину в Последней обители»</i></b><sup class=\"fn\">696</sup>."],["n",[[696,"Ибн Манда «аль-Иман», 903."]]],["p","544 ― Аль-А′радж передал со слов Абу Хурейры (да будет доволен им Аллах), что посланник Аллаха (да благословит его Аллах и приветствует) сказал: <b><i>«У каждого пророка была мольба, с которой он обращался, а я хочу приберечь свою мольбу, чтобы заступиться за свою общину в Последней обители»</i></b><sup class=\"fn\">697</sup>."],["n",[[697,"Малик в «аль-Муватта», стр. 212; аль-Бухари, 6304; Муслим, 198; Ахмад, 2/486; Ибн Хиббан, 6461; Ибн Манда в «аль-Иман», 901."]]],["p","545 ― Абу Зур′а передал со слов Абу Хурейры (да будет доволен им Аллах), что посланник Аллаха (да благословит его Аллах и приветствует) сказал: <b><i>«Каждому пророку (предоставлялась возможность) обратиться к Аллаху с мольбой, на которую (было обещано) дать ответ. И (каждый) обратился с такой мольбой, и ему был дарован ответ. Я же приберёг свою мольбу, чтобы заступиться за (членов) моей общины»</i></b><sup class=\"fn\">698</sup>."],["n",[[698,"Муслим, 199; Ибн Манда «аль-Иман», 911."]]],["p","546 ― ′Амр ибн Аби Суфьян ибн Джария ас-Сакафи передал, что Абу Хурейра (да будет доволен им Аллах) однажды сказал Ка′бу: <i>«Поистине, пророк Аллаха (да благословит его Аллах и приветствует) сказал: </i><b><i>\"У каждого пророка была мольба, с которой он обращался. А я, если пожелает Аллах, хочу приберечь свою мольбу, чтобы заступиться за свою общину в День Воскресения\"</i></b><i>»</i><sup class=\"fn\">699</sup>."],["n",[[699,"Муслим, 198; Ибн Манда «аль-Иман», 897, 898; аль-Аджурри в «аш-Шари′а», 842."]]]],[["p","547 ― Абу Салих передал со слов Абу Хурейры (да будет доволен им Аллах), что посланник Аллаха (да благословит его Аллах и приветствует) сказал: <b><i>«Поистине, каждому пророку (предоставлялась возможность) обратиться к Аллаху с мольбой, на которую (было обещано) дать ответ. И, поистине, я приберёг свою мольбу, чтобы заступиться за свою общину»</i></b><sup class=\"fn\">700</sup>."],["n",[[700,"Аль-Аджурри в «аш-Шари′а», 839."]]],["p","548 ― [Под этим номером приведено то же самое сообщение, что и под № 546]."],["p","549 ― Катада передал со слов Анаса ибн Малика (да будет доволен им Аллах), что пророк Аллаха (да благословит его Аллах и приветствует) сказал: <b><i>«У каждого пророка была мольба за свою общину, а я приберёг свою мольбу, чтобы заступиться за свою общину в День Воскресения»</i></b><sup class=\"fn\">701</sup>."],["n",[[701,"Муслим, 200; Ахмад, 3/292; Ибн Манда в «аль-Иман», 197; Абу Я′ля, 3022; Ибн Аби ′Асым в «ас-Сунна», 798."]]],["p","550 ― Абу Саляма передал со слов Абу Хурейры (да будет доволен им Аллах), что посланник Аллаха (да благословит его Аллах и приветствует) сказал: <b><i>«У каждого пророка была мольба, а я хочу приберечь свою мольбу, если пожелает Аллах, чтобы заступиться за свою общину в День Воскресения»</i></b><sup class=\"fn\">702</sup>."],["n",[[702,"Аль-Бухари, 7474; Муслим, 198; Ахмад, 2/381, 396; ад-Дарими, 2805, и др."]]],["p","551 ― Хаммам ибн Мунаббих передал со слов Абу Хурейры (да будет доволен им Аллах), что посланник Аллаха (да благословит его Аллах и приветствует) сказал: <b><i>«У каждого пророка была мольба, на которую (был обещан) ответ. А я, если пожелает Аллах, хочу отложить свою мольбу, чтобы заступиться за свою общину в День Воскресения»</i></b><sup class=\"fn\">703</sup>."],["n",[[703,"′Абд ур-Раззак в «Мусаннафе», 20864; Ибн Манда в «аль-Иман», 907."]]],["p","552 ― Мухаммад ибн Яхья слышал, как Абу Хурейра (да будет доволен им Аллах) говорил, что посланник Аллаха (да благословит его Аллах и приветствует) сказал: <b><i>«Поистине, у каждого пророка была мольба, с которой он обращался. Я же хочу приберечь свою мольбу, чтобы заступиться за свою общину».</i></b>"],["p","ГЛАВА 57: УПОМИНАНИЕ ДОВОДА НА ПРАВИЛЬНОСТЬ МОЕГО ТОЛКОВАНИЯ, КОГДА Я СКАЗАЛ, ЧТО В СЛОВАХ «ЙАД′У БИХА» ИМЕЕТСЯ ВИДУ «ОБРАТИЛСЯ С ЭТОЙ МОЛЬБОЙ»<sup class=\"fn\">704</sup>"],["n",[[704,"Дело в том, что в тех хадисах, которые привёл автор в прошлой главе, было сказано: «йад’у биха» (<span class=\"ar-i\" lang=\"ar\" dir=\"rtl\">يَدْعُو بِهَا</span>), иначе говоря, пришёл глагол, указывающий буквально на настоящее или будущее время. Буквальный перевод хадиса будет таким: «У каждого пророка была мольба, с которой он обратится». Ибн Хузейма (да будет доволен им Аллах) говорит о том, что хоть здесь и пришёл глагол настояще-будущего времени, но имеется в виду прошедшее время. То есть они уже обратились с этой мольбой. И вот в данной главе он приведёт версии, которые указывают на правильность его слов. Например, в некоторых версиях данный глагол уже приходит в прошедшем времени и говорится: «да’а биха» (<span class=\"ar-i\" lang=\"ar\" dir=\"rtl\">دَعَا بِهَا</span>), что означает «уже обратился с ней», и т. п. Можно сказать, что данная глава больше касается тонкостей арабского языка."]]]],[["p","553 ― Абу аз-Зубейр передал со слов Джабира (да будет доволен им Аллах), что пророк (да благословит его Аллах и приветствует) сказал: <b><i>«Поистине, у каждого пророка была мольба, с которой он уже обратился (к Аллаху). И, поистине, я приберёг свою мольбу, чтобы заступиться за свою общину в День Воскресения»</i></b><sup class=\"fn\">705</sup>."],["n",[[705,"Муслим, 201; Ахмад, 3/384; Ибн Хиббан, 6460, 6469, и др."]]],["p","554 ― Абу Салих передал со слов Абу Хурейры (да будет доволен им Аллах), что посланник Аллаха (да благословит его Аллах и приветствует) сказал: <b><i>«У каждого пророка была мольба, на которую (был обещан) ответ, и каждый пророк поспешил обратиться со своей мольбой, а я приберёг свою мольбу, чтобы заступиться за свою общину в День Воскресения. И (моё заступничество), если пожелает Аллах, обретёт тот из вас, кто умер, ничего не придавая Аллаху в сотоварищи»</i></b><sup class=\"fn\">706</sup>."],["n",[[706,"Муслим, 199; ат-Тирмизи, 3902; Ибн Маджа, 4307; Ахмад, 2/426, и др."]]],["p","555 ― Мухаммад ибн Зияд слышал, как Абу Хурейра (да будет доволен им Аллах) говорил, что посланник Аллаха (да благословит его Аллах и приветствует) сказал: <b><i>«Поистине, у каждого пророка была мольба, с которой он уже обратился относительно своей общины, и ему был дан ответ. И, поистине, я хочу, если пожелает Аллах, попросить Аллаха, чтобы Он сделал мою мольбу заступничеством за мою общину в День Воскресения»</i></b><sup class=\"fn\">707</sup>."],["n",[[707,"Муслим, 199; Ахмад, 2/409, 430, и др."]]],["p","556 ― Анас (да будет доволен им Аллах) передал, что пророк Аллаха (да благословит его Аллах и приветствует) сказал: <b><i>«Каждый пророк уже обратился с просьбой (или же он сказал: у каждого пророка была мольба, с которой он уже обратился относительно своего народа). Я же приберёг свою мольбу, чтобы заступиться за свою общину в День Воскресения»</i></b><sup class=\"fn\">708</sup>."],["n",[[708,"Муслим, 200; Ибн Манда в «аль-Иман», 918."]]],["p","557 ― [Под этим номером приведено то же самое сообщение, что и под № 556]."],["p","558 ― [Под этим номером приведено то же самое сообщение, что и под № 556]."],["p","559 ― [Под этим номером приведено то же самое сообщение, что и под № 555]."],["p","560 ― Катада передал со слов Анаса ибн Малика (да будет доволен им Аллах), что пророк (да благословит его Аллах и приветствует) сказал: <b><i>«Поистине, у каждого пророка была мольба, с которой он уже обратился относительно своей общины. И, поистине, я приберёг свою мольбу, чтобы заступиться за свою общину в День Воскресения».</i></b>"],["p","561 ― [Под этим номером приведено то же самое сообщение, что и под № 560]."],["p","562 ― Абу Са′ид аль-Худри (да будет доволен им Аллах) передал, что пророк (да благословит его Аллах и приветствует) сказал: <b><i>«Каждому пророку была дана мольба, и (каждый из них) поспешил (обратиться) с ней. А я отложил свою мольбу, чтобы заступиться за свою общину в День Воскресения. И, поистине, в моей общине будет человек, который заступится за большую группу людей. И будет такой, кто заступится за какое-то количество людей, и будут такие, кто заступится за трёх, двух или одного»</i></b><sup class=\"fn\">709</sup>."],["n",[[709,"Ахмад, 3/20; Абу Я′ля, 1014; ′Абд ибн Хумейд, 903; Ибн Аби Шейба, 31683."]]]],[["p","563 ― Аль-Хасан передал со слов Джабира ибн ′Абдуллаха (да будет доволен Аллах им и его отцом), что пророк (да благословит его Аллах и приветствует) сказал: <b><i>«У каждого пророка была мольба, с которой он уже обратился относительно своей общины. А я отложил свою мольбу, чтобы заступиться за свою общину в День Воскресения»</i></b><sup class=\"fn\">710</sup><b><i>.</i></b>"],["n",[[710,"Ахмад, 3/396; Ибн аль-Мубарак в «Муснаде», 105."]]],["p","ГЛАВА 58: УПОМИНАНИЕ ТОГО, ЧТО ВСЕМОГУЩИЙ И ВЕЛИКИЙ АЛЛАХ ДАЛ ВЫБОР СВОЕМУ ПРОРОКУ МУХАММАДУ (ДА БЛАГОСЛОВИТ ЕГО АЛЛАХ И ПРИВЕТСТВУЕТ) МЕЖДУ ТЕМ, ЧТОБЫ ОН ВВЁЛ ПОЛОВИНУ СВОЕЙ ОБЩИНЫ В РАЙ, И МЕЖДУ ЗАСТУПНИЧЕСТВОМ, И ПРОРОК (ДА БЛАГОСЛОВИТ ЕГО АЛЛАХ И ПРИВЕТСТВУЕТ) ВЫБРАЛ ДЛЯ СВОЕЙ ОБЩИНЫ ЗАСТУПНИЧЕСТВО, ИБО ОНО БУДЕТ БОЛЕЕ ОБШИРНЫМ И ПОЛЕЗНЫМ, ЧЕМ ПЕРВОЕ, И ОХВАТИТ БОЛЬШЕЕ КОЛИЧЕСТВО ЛЮДЕЙ ИЗ ЕГО ОБЩИНЫ, КОТОРАЯ ЯВЛЯЕТСЯ ЛУЧШЕЙ ИЗ ОБЩИН"],["p","564 ― ′Ауф ибн Малик аль-Ашджа′и (да будет доволен им Аллах) рассказывал: <i>«Однажды мы с посланником Аллаха (да благословит его Аллах и приветствует) остановились на привал, и когда я проснулся среди ночи, я не увидел в лагере ничего длиннее, чем спинка седла, ибо каждый человек и его верблюд прислонились к земле (и спали). Я встал и стал пробираться среди людей, пока не дошёл до места посланника Аллаха (да благословит его Аллах и приветствует), но его там не оказалось. Я положил руку на (его) ложе, но оно оказалось холодным. Я вышел, стал пробираться среди людей и говорить: \"Воистину, мы принадлежим Аллаху, и к Нему мы вернёмся! Посланника Аллаха (да благословит его Аллах и приветствует) увели!\". Так я прошёл весь лагерь, и увидел темное пятно. Я бросил камень и направился в сторону тёмного пятна, и оказалось, что это — Му′аз ибн Джабаль и Абу ′Убейда ибн аль-Джаррах, а перед нами раздавался звук, подобный шуму ручной мельницы или звуку тростника, когда его шевелит ветер. Мы сказали друг другу: \"О люди! Стойте тут до утра или пока не вернётся посланник Аллаха (да благословит его Аллах и приветствует)!\". Затем прошло столько времени, сколько пожелал Аллах, после чего он громко сказал: </i><b><i>\"А там есть Му′аз ибн Джабаль, Абу ′Убейда и ′Ауф ибн Малик?!\". </i></b><i>Мы ответили: \"Да!\". Тогда он подошёл к нам, и мы стали идти с ним, ничего у него не спрашивая, и он сам ничего не рассказал нам. А когда мы уже сели на ложе, он сказал: </i><b><i>\"Знаете ли вы, какой выбор предоставил мне мой Господь в эту ночь?!\". </i></b><i>Мы ответили: \"Аллах и Его посланник знают лучше!\". Тогда он сказал: </i><b><i>\"Он предоставил мне выбор между тем, чтобы ввести в Рай половину моей общины, и между заступничеством, и я выбрал заступничество\". </i></b><i>Мы сказали: \"О посланник Аллаха! Попроси Аллаха, чтобы Он сделал нас среди тех, кому оно будет дано!\". Он ответил: </i><b><i>\"Оно для каждого мусульманина!\"</i></b><i>»</i><sup class=\"fn\">711</sup>."],["n",[[711,"Аль-Аджурри в «аш-Шари′а», 847, 848; аль-Хаким в «аль-Мустадрак», 221; Ибн Манда в «аль-Иман», 932; ат-Табарани в «аль-Му′джам аль-Кабир», 18/68, и др."]]]],[["p","565 ― [Под этим номером приведено то же самое сообщение, что и под № 564]."],["p","566 ― [Под этим номером приведено то же самое сообщение, что и под № 564]."],["p","567 ― В другой версии пришло, что ′Ауф ибн Малик аль-Ашджа′и (да будет доволен им Аллах) рассказывал: <i>«Однажды мы находились в пути вместе с посланником Аллаха (да благословит его Аллах и приветствует), и каждый из нас лёг головой на ноги своего верхового животного (и спал). Когда я проснулся, я не увидел посланника Аллаха (да благословит его Аллах и приветствует), и отправился на его поиски. Вдруг я встретил Му′аза ибн Джабаля, которого испугало то же, что испугало меня, и вдруг мы услышали в верхней части долины шум, подобный тому, какой издаёт мельница. И когда мы пребывали в таком положении, вдруг пришёл пророк (да благословит его Аллах и приветствует) и сказал: </i><b><i>\"Ко мне пришёл посланец от моего Господа и предложил мне выбрать между тем, что Он введёт в Рай половину моей общины, и между заступничеством, и я выбрал заступничество\". </i></b><i>Мы сказали: \"Просим тебя ради Аллаха и ради сподвижничества, о посланник Аллаха, чтобы ты сделал нас одними из тех, за кого ты заступишься!\". Он сказал: </i><b><i>\"Вы будете среди тех, за кого я заступлюсь!\". </i></b><i>Затем мы отправились к людям, и оказалось, что они испугались, когда потеряли посланника Аллаха (да благословит его Аллах и приветствует). Пророк (да благословит его Аллах и приветствует) подошёл к ним и сказал: </i><b><i>\"Ко мне пришёл посланец от моего Господа и предложил мне выбрать между тем, что Он введёт в Рай половину моей общины, и между заступничеством, и я выбрал заступничество\". </i></b><i>Люди сказали: \"О пророк Аллаха! Просим тебя ради Аллаха и ради сподвижничества, о посланник Аллаха, чтобы ты сделал нас одними из тех, за кого ты заступишься!\". Он сказал: </i><b><i>\"Вы будете среди тех, за кого я заступлюсь!\". </i></b><i>А когда люди стало уже очень много, он сказал: </i><b><i>\"Моё заступничество (ждёт) каждого (члена) моей общины, который умер, ничего не придавая Аллаху в сотоварищи\"</i></b><i>»</i><sup class=\"fn\">712</sup>."],["n",[[712,"Ахмад, 6/28; ат-Тирмизи, 2441; Ибн Хиббан, 6470; аль-Аджурри в «аш-Шари′а», 846; аль-Хаким в «аль-Мустадрак», 222; Ибн Аби ′Асым в «ас-Сунна», 818; Ибн Аби Шейба в «Мусаннафе», 31751."]]],["p","568 ― В другой версии пришло, что пророк (да благословит его Аллах и приветствует) сказал: <b><i>«Поистине, я призываю в свидетели тех, кто присутствует со мной, что моё заступничество (ждёт) каждого (члена) моей общины, который умер, ничего не придавая Аллаху в сотоварищи</i></b><i>»</i>."],["p","569 ― [Под этим номером приведено то же самое сообщение]."],["p","570 ― [Под этим номером приведено то же самое сообщение]."]],[["p","571 ― [Под этим номером приведено то же самое сообщение]."],["p","572 ― [Под этим номером приведено сообщение, связанное с цепочками передатчиков хадисов]."],["p","573 ― [Под этим номером приведено сообщение, связанное с цепочками передатчиков хадисов]."],["p","574 ― [Под этим номером приведено примерно то же самое сообщение, что и под № 564]."],["p","575 ― [Под этим номером приведено примерно то же самое сообщение, что и под № 564]."],["p","576 ― [Под этим номером приведено примерно то же самое сообщение, что и под № 564, но уже со слов Абу Мусы аль-Аш′ари (да будет доволен им Аллах)]."],["p","577 ― [Под этим номером приведено примерно то же самое сообщение, что и под № 564]<sup class=\"fn\">713</sup>."],["n",[[713,"Мы опустили многие хадисы этой главы, так как они ничем существенным не отличаются от тех, что мы поместили в нашем переводе. Автор (да помилует его Аллах) просто приводит разные пути передачи и разные версии одного и того же хадиса. В них нет никаких существенных отличий, и поэтому они были опущены для удобства читателя."]]],["p","ГЛАВА 59: УПОМИНАНИЕ ДОВОДА, УКАЗЫВАЮЩЕГО НА ТО, ЧТО НЕКОТОРЫЕ ПРОРОКИ, КОТОРЫЕ ЖИЛИ ДО НАШЕГО ПРОРОКА (ДА БЛАГОСЛОВИТ АЛЛАХ И ПРИВЕТСТВУЕТ ЕГО И ВСЕХ ИХ) И КОТОРЫМ БЫЛА ДАРОВАНА МОЛЬБА, НА КОТОРУЮ АЛЛАХ ОБЕЩАЛ ИМ ОТВЕТИТЬ, ОБРАТИЛИСЬ С ЭТОЙ МОЛЬБОЙ ПРОТИВ СВОЕГО НАРОДА, ЧТОБЫ ОНИ ПОГИБЛИ В ЭТОМ МИРЕ"],["p","Этот довод также указывает на то, что среди них не было никого более сострадательного к своей общине, чем наш пророк Мухаммад (да благословит его Аллах и приветствует), ведь он приберёг свою мольбу, чтобы заступиться за членов своей общины в День Воскресения."],["p","578 ― ′Абд ур-Рахман ибн Аби ′Акыль ас-Сакафи (да будет доволен им Аллах) рассказывал: <i>«Я прибыл к посланнику Аллаха (да благословит его Аллах и приветствует) в составе делегации племени сакы́ф, и мы пошли по одной из улиц Медины, пока не остановились у двери. Причём тогда не было никого более ненавистного нам среди людей, чем тот, к кому мы собирались войти. Мы вошли, поприветствовали (его) салямом и присягнули (ему), а когда мы вышли от него, не было никого более любимого нам среди людей, чем тот, от кого мы вышли. Я сказал ему: \"О посланник Аллаха! Разве ты не просил у своего Господа власти, подобной власти Сулеймана?\". Он засмеялся и ответил: </i><b><i>\"Быть может, у вашего товарища есть у Аллаха нечто лучшее, чем власть Сулеймана. Поистине, Аллах не посылал ни одного пророка без того, чтобы даровать ему мольбу, (на которую обязательно будет дан ответ). Некоторые из них попросили о чем-либо мирском, и это было даровано им. Некоторые из них обратились с этой мольбой против своих соплеменников, и по причине этой мольбы те были погублены. Поистине, Всевышний Аллах даровал и мне (такую) мольбу, но я припас ее у своего Господа, чтобы заступиться за (членов) своей общины в День Воскресения\"</i></b><i>»</i><sup class=\"fn\">714</sup><i>.</i>"],["n",[[714,"Аль-Хаким в «аль-Мустадрак», 226; Ибн Аби ′Асым в «ас-Сунна», 824; Ибн Аби Шейба в «Мусаннафе», 31740, и др."]]]],[["p","579 ― [Под этим номером приведено примерно то же самое сообщение, что и под № 578]."],["p","ГЛАВА 60: УПОМИНАНИЕ ВЕРСИИ, ПЕРЕДАННОЙ ОТ ПРОРОКА (ДА БЛАГОСЛОВИТ ЕГО АЛЛАХ И ПРИВЕТСТВУЕТ), В КОТОРОЙ УПОМИНАЕТСЯ ЗАСТУПНИЧЕСТВО (ШАФА′АТ) И КОТОРУЮ МУ′ТАЗИЛИТЫ, ХАРИДЖИТЫ И МНОГИЕ ДРУГИЕ СТОРОННИКИ НОВШЕСТВ ИЗ-ЗА СВОЕГО НЕВЕЖЕСТВА И МАЛЫХ ПОЗНАНИЙ ХАДИСОВ ПОСЧИТАЛИ ПРОТИВОРЕЧАЩЕЙ ДРУГИМ СЛОВАМ ПРОРОКА (ДА БЛАГОСЛОВИТ ЕГО АЛЛАХ И ПРИВЕТСТВУЕТ), В КОТОРЫХ ГОВОРИТСЯ О ТОМ, ЧТО ОН БУДЕТ ЗАСТУПАТЬСЯ ЗА КАЖДОГО МУСУЛЬМАНИНА"],["p","Но хвала Аллаху и по Его милости всё не так, как полагают эти невежды, и я разъясню с помощью нашего Всемогущего и Великого Творца, что эти хадисы не противоречат друг другу."],["p","580 ― Са́бит передал со слов Анаса (да будет доволен им Аллах), что пророк (да благословит его Аллах и приветствует) сказал: <b><i>«Я буду заступаться за (членов) моей общины, совершавших тяжкие грехи»</i></b><sup class=\"fn\">715</sup>."],["n",[[715,"Ат-Тирмизи, 2435; Ибн Хиббан, 6468; аль-Хаким в «аль-Мустадрак», 228; аль-Бейхакы в «ас-Сунан аль-кубра», 8/17, и др."]]],["p","581 ― [Под этим номером приведено то же самое сообщение, что и под № 580]<sup class=\"fn\">716</sup>."],["n",[[716,"Здесь приведен тот же самый хадис, только с другой цепочкой передачи. Его по этой цепочке передали Абу Дауд, 4739; Ахмад, 3/213; аль-Аджурри в «аш-Шари′а», 833, и др."]]],["p","582 ― [Под этим номером приведено то же самое сообщение, что и под № 580]."],["p","583 ― [Под этим номером приведено то же самое сообщение, что и под № 580]<sup class=\"fn\">717</sup>."],["n",[[717,"Здесь приведен тот же самый хадис, но уже со слов Джабира ибн ′Абдуллаха (да будет доволен Аллах им и его отцом). С его слов этот хадис передали ат-Тирмизи, 2436; аль-Аджурри в «аш-Шари′а», 830, 831, и др."]]],["p","584 ― [Под этим номером приведено то же самое сообщение, что и под № 580]."],["p","585 ― [Под этим номером приведено то же самое сообщение, что и под № 580]."],["p","586 ― [Под этим номером приведено то же самое сообщение, что и под № 580]<sup class=\"fn\">718</sup>."],["n",[[718,"Во всех этих версиях текст хадиса одинаков, но отличаются только пути его передачи."]]],["p","В предыдущих главах мы упоминали слова пророка (да благословит его Аллах и приветствует) о том, что он будет заступаться за каждого мусульманина. Он имел в виду, что он будет заступаться за всех мусульман, прежде чем это сделают остальные пророки, мученики, праведники и все другие мусульмане. Посредством этого его заступничества Аллах избавит их от стояния, при котором их постигнут тревоги и печали. Он заступится, чтобы Аллах рассудил их и ускорил их расчёт, что было разъяснено подробно в тех хадисах, которые я приводил ранее."],["p","Что же касается слов пророка (да благословит его Аллах и приветствует): <b><i>«Я буду заступаться за (членов) моей общины, совершавших тяжкие грехи», </i></b>то он имел в виду другое заступничество после того первого заступничества, которое охватывало всех мусульман. Здесь речь идёт уже о заступничестве за тех верующих, кого ввели в Ад из-за их грехов и проступков, которые Аллах не простил им в ближней жизни. Такие выйдут из Огня через заступничество пророка (да благословит его Аллах и приветствует)."]],[["p","В словах пророка (да благословит его Аллах и приветствует): <b><i>«Я буду заступаться за (членов) моей общины, совершавших тяжкие грехи», </i></b>речь идёт о тех, кто совершал тяжкие грехи, и из-за этого попал в Ад. Ведь Всемогущий и Великий Аллах обещал простить малые грехи тем, кто сторонился тяжких грехов, как мы уже разъясняли. Это пришло в словах Всевышнего: <b>«Если вы будете избегать тяжких грехов из того, что вам запрещено, то Мы простим ваши дурные поступки»</b><sup class=\"fn\">719</sup>."],["n",[[719,"Сура «ан-Ниса», аят 31."]]],["p","Посланник Аллаха (да благословит его Аллах и приветствует) попросил своего Всемогущего и Великого Творца, чтобы Он позволил ему заступиться за тех членов его общины, которые проливали кровь друг друга. На эту его мольбу был дан ответ, хотя пролитие крови мусульман без права на то — это один из самых тяжких грехов. И нет более тяжкого греха после придания Аллаху сотоварищей и неверия, чем этот грех."],["p","587 ― Анас ибн Малик (да будет доволен им Аллах) передал со слов Умм Хабибы (да будет доволен ею Аллах), что пророк (да благословит его Аллах и приветствует) сказал: <b><i>«Мне было показано то, что встретят (члены) моей общины после моей (смерти), и то, что они будут проливать кровь друг друга, (однако все) это предопределил Аллах так же, как Он предопределил это среди (членов) общин, живших прежде них. Затем я попросил Его, чтобы Он позволил мне заступиться за них в День Воскресения, и Он позволил (мне)»</i></b><sup class=\"fn\">720</sup>."],["n",[[720,"Ибн Аби ′Асым в «ас-Сунна», 800; аль-Хаким, 227, и др."]]],["p","ГЛАВА 61: УПОМИНАНИЕ ДОВОДА, УКАЗЫВАЮЩЕГО НА ТО, ЧТО ПРОРОК (ДА БЛАГОСЛОВИТ ЕГО АЛЛАХ И ПРИВЕТСТВУЕТ) ПОД ТЯЖКИМИ ГРЕХАМИ В ЭТОМ ХАДИСЕ ИМЕЛ В ВИДУ ТЕ ГРЕХИ, КОТОРЫЕ МЕНЬШЕ МНОГОБОЖИЯ"],["p","Пророк (да благословит его Аллах и приветствует) сообщил о том, что многобожие (ширк) — это самый великий грех, а когда он сказал: <b><i>«Я буду заступаться за (членов) моей общины, совершавших тяжкие грехи», </i></b>он имел в виду тех людей, которые ответили на его призыв, уверовали него и раскаялись в многобожии. Словом «умма» (община) называют ещё и всех тех, к кому он был послан<sup class=\"fn\">721</sup>. Но те, которые уверовали и раскаялись в многобожии, являются той его общиной, которая ответила на его призыв, а до этого они относились к той общине, которую он призывал к вере."],["n",[[721,"Речь идёт о том, что под фразой «община Мухаммада (да благословит его Аллах и приветствует)» (умма Мухаммада), могут иметься в виду две категории: Во-первых, то, что учёные называют «уммат уль-иджаба», то есть те люди, которые ответили на его призыв. Иначе говоря, мусульмане и верующие. Во-вторых, то, что учёные называют «уммат ад-да’ва» (община призыва), то есть все те, к кому он был послан. В эту категорию входят также неверующие. Их тоже можно назвать его общиной, если имеется в виду второй смысл («уммат ад-да’ва»), а не первый («уммат уль-иджаба»). Автор (да помилует его Аллах) разъясняет, что когда в этом хадисе пришли слова <b><i>«за (членов) моей общины»</i></b>, то имеется в виду «уммат уль-иджаба». А далее он приведёт хадис, указывающий на то, что многобожники и неверующие не удостоятся его заступничества."]]]],[["p","588 ― Аль-А′маш передал со слов Абу Хурейры (да будет доволен им Аллах), что пророк (да благословит его Аллах и приветствует) сказал: <b><i>«И (моё заступничество), если пожелает Аллах, обретёт тот из них, кто умер, ничего не придавая Аллаху в сотоварищи»</i></b><sup class=\"fn\">722</sup>."],["n",[[722,"Полная версия данного хадиса была приведена под № 554."]]],["p","ГЛАВА 62: РАЗЪЯСНЕНИЕ ТОГО, ЧТО ЗАСТУПНИЧЕСТВО ПРОРОКА (ДА БЛАГОСЛОВИТ ЕГО АЛЛАХ И ПРИВЕТСТВУЕТ) ЗА ТЕХ, КТО СОВЕРШАЛ ТЯЖКИЕ ГРЕХИ, НЕОБХОДИМО ПОНИМАТЬ ИМЕННО ТАК, КАК Я РАЗЪЯСНИЛ. ТО ЕСТЬ ОНО БУДЕТ ЗА ТЕХ, КТО ПОПАЛ В АД, НО НЕ ОТНОСИЛСЯ К ЕГО ВЕЧНЫМ ОБИТАТЕЛЯМ. РЕЧЬ ИДЁТ О ЕДИНОБОЖНИКАХ, КОТОРЫЕ СОВЕРШАЛИ ГРЕХИ И ПРОСТУПКИ И БЫЛИ ВВЕДЕНЫ В АД, ЧТОБЫ ИХ ПОСТИГЛО ЕГО ПЛАМЯ"],["p","589 ― Абу Надра передал со слов Абу Са′ида аль-Худри (да будет доволен им Аллах), что пророк (да благословит его Аллах и приветствует) сказал: <b><i>«Что касается обитателей Огня, которые останутся в нём (навечно), то они не умрут там, но и жить не будут. Но будут еще и люди, которые коснётся Огонь за их грехи и проступки, и когда они сгорят, будет разрешено заступаться, после чего их станут приводить отдельными группами и бросать в райские реки. А потом будет сказано: \"О обитатели Рая, лейте на них воду\", и они станут прорастать, как прорастает семя, оказавшееся в том, что приносит с собой поток»</i></b><sup class=\"fn\">723</sup>."],["n",[[723,"Муслим, 185; Ахмад, 3/87; Ибн Манда в «аль-Иман», 830."]]],["p","590 ― [Под этим номером приведено то же самое сообщение, что и под № 589]."],["p","591 ― Катада передал со слов Анаса ибн Малика (да будет доволен им Аллах), что пророк (да благословит его Аллах и приветствует) сказал: <b><i>«Некоторых людей по причине грехов, совершённых ими, Огонь будет обжигать, оставляя на них следы, а затем Аллах введёт их в Рай. Их будут называть \"джаханнамийюн\"</i></b><sup class=\"fn\">724</sup><b><i>»</i></b><sup class=\"fn\">725</sup><b><i>.</i></b>"],["n",[[724,"От слова «джаханнам» (адское пламя, геенна)."],[725,"Аль-Бухари, 7450; Ахмад, 3/133, и др."]]],["p","592 ― [Под этим номером приведено примерно то же самое сообщение, что и под № 591]."],["p","593 ― [Под этим номером приведено примерно то же самое сообщение, что и под № 591]."],["p","594 ― [Под этим номером приведено примерно то же самое сообщение, что и под № 591]."],["p","595 ― Са́бит передал, что Анас (да будет доволен им Аллах) слышал, как посланник Аллаха (да благословит его Аллах и приветствует) сказал: <b><i>«Поистине, некоторые люди выйдут из Огня после того, как Огонь обожжёт их и оставит на них следы в качестве наказания за грехи, совершённые ими. Затем Аллах выведет их по Своей милости, и они войдут в Рай»</i></b><sup class=\"fn\">726</sup>."],["n",[[726,"Эту версию передал ′Абд ур-Раззак в «Мусаннафе», 20859."]]],["p","596 ― В другой версии со слов Анаса (да будет доволен им Аллах) пришло, что посланник Аллаха (да благословит его Аллах и приветствует) сказал: <b><i>«Увидев их, обитатели Рая скажут: \"Кто они?\", и им ответят: \"Это — джаханнамийюн\"»</i></b><sup class=\"fn\">727</sup><b><i>.</i></b>"],["n",[[727,"Эту версию передали Ибн Аби ′Асым в «ас-Сунна», 847; ат-Табарани в «аль-Аусат», 2882."]]]],[["p","597 ― Хузейфа (да будет доволен им Аллах) передал, что пророк (да благословит его Аллах и приветствует) сказал: <b><i>«Посредством заступничества заступников Аллах выведет из Огня людей, от которых будет исходить неприятный запах, ибо их уже коснулся Огонь. После этого они войдут в Рай, и их будут называть \"джаханнамийюн\"»</i></b><sup class=\"fn\">728</sup>."],["n",[[728,"Ахмад, 5/402; аль-Аджурри в «аш-Шари′а», 859, и др."]]],["p","598 ― ′Имран (да будет доволен им Аллах) передал, что пророк (да благословит его Аллах и приветствует) сказал: <b><i>«Некоторые люди выйдут из Огня посредством заступничества, и их будут называть \"джаханнамийюн\"»</i></b><sup class=\"fn\">729</sup>."],["n",[[729,"Аль-Бухари, 6566; ат-Тирмизи, 2600, и др."]]],["p","599 ― Подобный хадис также передан со слов Ибн ′Аббаса (да будет доволен Аллах им и его отцом)."],["p","600 ― [Под этим номером приведено примерно то же самое сообщение, что и под № 597]."],["p","601 ― В другой версии со слов ′Имрана ибн Хусайна (да будет доволен им Аллах) пришло, что пророк (да благословит его Аллах и приветствует) сказал: <b><i>«Выйдут из Огня люди, которых будут называть \"джаханнамийюн\", и (это произойдёт) посредством заступничества Мухаммада». </i></b>"],["p","602 ― [Под этим номером приведено примерно то же самое сообщение, что и под № 589]<sup class=\"fn\">730</sup>."],["n",[[730,"Здесь приведён тот же самый хадис, но только по другой цепочке передатчиков. Его по этой цепочке передали Ахмад, 3/90; Ибн Манда в «аль-Иман», 835; Абу Я′ля, 1255."]]],["p","603 ― ′Абдуллах ибн ′Амр (да будет доволен Аллах им и его отцом) передал, что посланник Аллаха (да благословит его Аллах и приветствует) сказал: <b><i>«Из Огня выйдут (некоторые) люди, и их будут называть \"джаханнамийюн\"». </i></b>"],["p","Передатчик этого хадиса сказал: <i>«Я спросил ′Абдуллаха ибн ′Амра: \"Ты слышал это от посланника Аллаха (да благословит его Аллах и приветствует)?\". Он ответил: \"Да!\"»</i><sup class=\"fn\">731</sup>."],["n",[[731,"Цепочка передатчиков этой версии является очень слабой, хоть и сам хадис достоверный."]]],["p","604 ― [Под этим номером приведено примерно то же самое сообщение, что и под № 603]."],["p","605 ― ′Амр ибн Дина́р передал от Джабира ибн ′Абдуллаха (да будет доволен Аллах им и его отцом), что пророк (да благословит его Аллах и приветствует) сказал: <b><i>«Поистине, Аллах выведет некоторых людей из Огня посредством заступничества»</i></b><sup class=\"fn\">732</sup>."],["n",[[732,"Аль-Бухари, 6558; Муслим, 191, и др."]]],["p","606 ― [Под этим номером приведено примерно то же самое сообщение, что и под № 605]."],["p","607 ― [Под этим номером приведено примерно то же самое сообщение, что и под № 605]."],["p","608 ― [Под этим номером приведено примерно то же самое сообщение, что и под № 605]."],["p","609 ― В другой версии со слов Анаса (да будет доволен им Аллах) пришло, что пророк (да благословит его Аллах и приветствует) сказал: <b><i>«Поистине, из Огня выйдут некоторые люди после того, как их коснётся адское пламя и оставит на них след. Затем они войдут в Рай и обитатели Рая будут называть их \"джаханнамийюн\"»</i></b><sup class=\"fn\">733</sup>."],["n",[[733,"Аль-Бухари, 6559, и др."]]]]];
